import Foundation

public enum AppLanguage: String, CaseIterable, Identifiable, Sendable {
    case english = "en", spanish = "es", chinese = "zh-Hans", russian = "ru"
    public var id: String { rawValue }
    public var name: String {
        switch self { case .english: "English"; case .spanish: "Español"; case .chinese: "简体中文"; case .russian: "Русский" }
    }
    public var locale: Locale { Locale(identifier: rawValue) }
    var index: Int { switch self { case .english: 0; case .spanish: 1; case .chinese: 2; case .russian: 3 } }
}

public enum AppLocalization {
    public static func text(_ source: String, language: AppLanguage) -> String { catalog[source]?[language.index] ?? source }
    public static func format(_ source: String, language: AppLanguage, _ arguments: CVarArg...) -> String {
        String(format: text(source, language: language), locale: language.locale, arguments: arguments)
    }
    public static func time(_ date: Date, language: AppLanguage, timeZone: TimeZone = .current) -> String {
        var style = Date.FormatStyle(date: .omitted, time: .shortened).locale(language.locale)
        style.timeZone = timeZone
        return date.formatted(style)
    }
    public static func entryCount(_ count: Int, language: AppLanguage) -> String {
        switch language {
        case .english: return "\(count) " + (count == 1 ? "entry" : "entries")
        case .spanish: return "\(count) " + (count == 1 ? "entrada" : "entradas")
        case .chinese: return "\(count) 个条目"
        case .russian:
            let last = count % 10, hundred = count % 100
            let word = (11...14).contains(hundred) ? "записей" : (last == 1 ? "запись" : ((2...4).contains(last) ? "записи" : "записей"))
            return "\(count) \(word)"
        }
    }
